package org.springframework.samples.petclinic.owner;

import static org.springframework.samples.petclinic.owner.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.owner.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.owner.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.owner.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * GET /api/owners/{ownerId} - OwnerRestController.getOwner
 * auth: JWT bearer (SecurityConfig requires authenticated for /api/**; token via POST /api/auth/login, hardcoded admin/password user in CustomUserDetailsService, no DB dependency)
 * RED param: ownerId (Integer path variable, DB_WHERE via OwnerRepository.findById) - NULL/EMPTY mutations not applicable to a mandatory path segment (ambiguous route match); covered instead by WHITE_SPACE/SPECIAL_CHAR/INVALID_FORMAT/LENGTH_EXCEEDED which deterministically hit Spring's Integer path-variable type-conversion failure (400)
 * fixture: one owner with two pets (Buddy has a visit, Zelda has none) to exercise nested pets[]/visits[] serialization ordered by pet name
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class OwnerGetBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "SEQ", Long.toString(seq),
                "PET1_ID", Long.toString(seq + 1),
                "PET2_ID", Long.toString(seq + 2),
                "VISIT_ID", Long.toString(seq + 3));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/owner-get-teardown.sql", p);
        executeSqlTemplate("sql/owner-get-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_getOwner_returnsOwnerCoreFields(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("NimbusFirst"))
                    .body("lastName", equalTo("NimbusOwner"))
                    .body("address", equalTo("1 Nimbus Way"))
                    .body("city", equalTo("TestCity"))
                    .body("telephone", equalTo("5551234567"));
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_returnsFirstPetWithTypeAndVisit(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("pets[0].name", equalTo("Buddy"))
                    .body("pets[0].birthDate", equalTo("2015-05-01"))
                    .body("pets[0].type.name", equalTo("cat"))
                    .body("pets[0].visits[0].date", equalTo("2023-01-10"))
                    .body("pets[0].visits[0].description", equalTo("Annual checkup"));
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_returnsSecondPetWithoutVisits(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("pets[1].name", equalTo("Zelda"))
                    .body("pets[1].type.name", equalTo("dog"))
                    .body("pets[1].visits.size()", equalTo(0));
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_INVALID_FORMAT(TestInfo info) {
        // non-numeric path segment -> Integer conversion failure
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "abc")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_WHITE_SPACE(TestInfo info) {
        // blank path segment -> Integer conversion failure
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", " ")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_SPECIAL_CHAR(TestInfo info) {
        // SQL-injection-shaped path segment -> Integer conversion failure (also proves no SQLi passthrough)
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "1' OR '1'='1")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_LENGTH_EXCEEDED(TestInfo info) {
        // numeric literal beyond Integer range -> NumberFormatException
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "99999999999999999999")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }

    @Test
    void ATC_getOwner_notFound(TestInfo info) {
        // well-formed id with no matching row (below idOffset, outside seeded ranges)
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "123456789")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owner-get-teardown.sql", p);
        }
    }
}

